    def perform_commissioning(self, scf_file, timeout=30):
        plan_name = path.splitext(path.split(scf_file)[1])[0]
        self.add_plan_to_staging(scf_file=scf_file, plan_name=plan_name, timeout=timeout)
        staged_plans = self._send_get_request(endpoint="/staged-plans", timeout=timeout)

        return self.activate_staged_plan(staged_plans=staged_plans, plan_name=plan_name, timeout=timeout)

    def add_plan_to_staging(self, scf_file, plan_name, timeout=30):
        with open(scf_file, "rb") as file:
            multipart_data = MultipartEncoder(
                fields={"planFile": (plan_name, file, "text/xml"),
                        "planName": plan_name})

            headers = {
                "Content-Type": multipart_data.content_type,
            }

            self._send_post_request(endpoint="/staged-plans/actions/downloads", data=str(multipart_data),
                                    timeout=timeout, headers=headers, log_payload=False)

        time.sleep(5)   # Wait for the plan to be staged

    def activate_staged_plan(self, staged_plans, plan_name, timeout):
        for plan in staged_plans:
            if plan["planName"] == plan_name:
                plan_id = plan["planId"]

                response = self._send_post_request(endpoint=f"/staged-plans/{plan_id}/operations/activations",
                                                   timeout=timeout,
                                                   headers={"Content-Type": "application/json"})
                response["planId"] = plan_id
                return response

    def get_status_of_perform_commissioning(self, plan_id, operation_id, timeout=30):
        return self._send_get_request(endpoint=f"/staged-plans/{plan_id}/operations/activations/{operation_id}",
                                      timeout=timeout)

