    def trigger_local_snapshot(self, filter_regx, coverage, originator, timeout=30, sdl_components=None, include_sdl_history_recordings=False):
        endpoint = '/snapshot/operations/locals'
        headers = {
            "accept": "application/json",
            "Content-Type": "application/json",
        }
        data = {
            "coverage": coverage,
            "originator": originator,
            "heartbeat": True,
            "includeSdlHistoryRecordings": include_sdl_history_recordings,
            "filterRegx": filter_regx
        }

        if sdl_components:
            data["namespaceKeyPrefixes"] = {"components": sdl_components}

        not_null_data = {key:value for key, value in data.items() if value}

        return self._send_post_request(endpoint=endpoint, headers=headers, json=not_null_data, timeout=timeout)

